@extends('layouts.app') @section('title','Attendance Adjustments') @section('page-title','Attendance Adjustments')
@section('content')
<div x-data="adjustmentList({{ Illuminate\Support\Js::from($adjustments) }})" class="space-y-4"><div class="flex justify-end"><select x-model="filter" class="rounded border p-2.5" aria-label="Filter adjustment status"><option value="">All requests</option><option>Pending</option><option>Approved</option><option>Rejected</option></select></div><div class="overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-gray-50"><tr><th class="p-3">Requested</th><th class="p-3">Employee</th><th class="p-3">Original record</th><th class="p-3">Requested change</th><th class="p-3">Reason</th><th class="p-3">Status</th><th class="p-3">Actions</th></tr></thead><tbody><template x-for="r in filtered" :key="r.id"><tr class="border-t"><td class="p-3" x-text="r.date_requested"></td><td class="p-3" x-text="r.full_name"></td><td class="p-3" x-text="`${r.work_date}: ${r.original_time_in||'—'} – ${r.original_time_out||'—'}`"></td><td class="p-3" x-text="`${r.requested_time_in||'—'} – ${r.requested_time_out||'—'}`"></td><td class="p-3" x-text="r.reason"></td><td class="p-3"><span x-text="r.status" class="rounded-full bg-teal-100 px-2 py-1"></span></td><td class="p-3 whitespace-nowrap"><button @click="selected=r;modal='details'" class="text-teal-800 underline">Details</button><template x-if="r.status==='Pending'"><span> <button @click="selected=r;modal='approve'" class="text-green-800 underline">Approve</button> <button @click="selected=r;modal='reject'" class="text-red-800 underline">Reject</button></span></template></td></tr></template><tr x-show="!filtered.length"><td colspan="7" class="p-8 text-center text-gray-700">No adjustment requests match this filter.</td></tr></tbody></table></div>
<div x-show="modal==='details'" x-cloak class="fixed inset-0 z-40 grid place-items-center bg-black/50 p-4"><div x-trap.inert.noscroll="modal==='details'||modal==='approve'||modal==='reject'" role="dialog" aria-modal="true" class="w-full max-w-xl rounded-xl bg-white p-6"><h2 class="text-lg font-semibold">Adjustment details</h2><pre class="my-4 whitespace-pre-wrap text-sm" x-text="JSON.stringify(selected,null,2)"></pre><button @click="modal=''" class="rounded border px-4 py-2">Close</button></div></div>
<div x-show="modal==='approve'||modal==='reject'" x-cloak class="fixed inset-0 z-40 grid place-items-center bg-black/50 p-4"><div x-trap.inert.noscroll="modal==='details'||modal==='approve'||modal==='reject'" role="dialog" aria-modal="true" class="w-full max-w-md rounded-xl bg-white p-6"><h2 class="text-lg font-semibold" x-text="modal==='approve'?'Approve adjustment?':'Reject adjustment?' "></h2><template x-if="modal==='reject'"><label class="mt-3 block text-sm">Reason<textarea x-model="rejectReason" required maxlength="500" class="mt-1 block w-full rounded border p-2.5"></textarea></label></template><div class="mt-4 flex justify-end gap-2"><button @click="modal='';rejectReason=''" class="rounded border px-4 py-2">Cancel</button><button @click="finish()" class="rounded bg-[#0b1f33] px-4 py-2 text-white">Confirm</button></div></div></div></div>
<script>function adjustmentList(rows){return {rows,filter:'',modal:'',selected:null,rejectReason:'',get filtered(){return this.rows.filter(r=>!this.filter||r.status===this.filter)},finish(){if(this.modal==='reject'&&!this.rejectReason.trim())return;this.selected.status=this.modal==='approve'?'Approved':'Rejected';this.modal='';this.rejectReason='';this.$dispatch('show-toast',{message:'Adjustment '+this.selected.status.toLowerCase()+' (demo).'})}}}</script>
@endsection
